struct OrderDraft {
    let rows: [Row]
    lazy var publishIssues: [Issue] = rows.filter { $0.qty <= 0 }.map(\.issue)  // on first access

    func validateForPublish() throws {
        guard publishIssues.isEmpty else { throw ValidationError(publishIssues) }  // gate
    }
}

try draft.validateForPublish(); try store.commit(draft)                        // after the gate
